    private func isComparison(_ q: String) -> Bool {
        let l = q.lowercased()
        return l.contains(" or ") || l.contains(" vs") || l.contains("bigger")
            || l.contains("more at") || l.contains("more on") || l.contains("more often")
            || l.contains("difference") || l.contains("which was") || l.contains("compare")
    }
    private func isRowIndex(_ q: String) -> Bool { q.contains("transaction #") }

    /// Parse "£21.02" → 2102 pence; nil if not a money string.
    static func firstPence(_ s: String) -> Int? { allPence(s).first }
    /// Every "£X.XX" figure in a string, as pence.
    static func allPence(_ s: String) -> [Int] {
        var out: [Int] = []
        let clean = s.replacingOccurrences(of: ",", with: "")
        let rx = try! NSRegularExpression(pattern: #"£(\d+)\.(\d{2})"#)
        for m in rx.matches(in: clean, range: NSRange(clean.startIndex..., in: clean)) {
            guard let wr = Range(m.range(at: 1), in: clean), let fr = Range(m.range(at: 2), in: clean),
                  let w = Int(clean[wr]), let f = Int(clean[fr]) else { continue }
            out.append(w * 100 + f)
        }
        return out
    }

    // Questions the app deliberately routes to the on-device model, not the
    // deterministic router: multi-merchant synthesis (parenthetical lists),
    // foreign-currency reasoning, multi-step share math, and per-day averages.
    private func isLLMTerritory(_ q: String) -> Bool {
        let l = q.lowercased()
        return l.contains("(")                        // "subscriptions (Apple, Amazon…)"
            || l.contains("pre-fee") || l.contains("isk") || l.contains("conversion")
            || l.contains("reasonable") || l.contains("krona")
            || l.contains("single biggest day") || l.contains("share of total")
            || l.contains("cut out all") || l.contains("halving") || l.contains("pub and bar")
            || l.contains("per active day") || l.contains("per day")
            // multi-merchant "X and Y combined": the deterministic token-matcher
            // can't reliably disambiguate merchants that share a token (Prime
            // Video vs Amazon Prime) or whose rows have glued descriptions —
            // routed to the on-device model instead.
            || l.contains("combined")
    }

    // Run all generated questions through the router. Each file group is answered
    // against ITS OWN rows fixture: set 1 + set 2 are the single-month statement
    // (`rows`), set 3 is the 3-month heavy statement (`rows3`).
    func testAll2000ThroughRouter() throws {
        var answered = 0, deferred = 0, checkable = 0, llmTerritory = 0
        var wrong: [String] = []
        let groups: [(rows: [TxnRow], files: [String])] = [
            (Self.rows,  ["amex_qa_2000.jsonl", "amex_qa_2000_set2.jsonl"]),
            (Self.rows3, ["amex_qa_2000_set3.jsonl"]),
            (Self.rows6, ["amex_qa_10000_set4.jsonl"]),
            (Self.rows12, ["amex_qa_20000_set5.jsonl"]),
            (Self.rows1000, ["amex_qa_10000_set6.jsonl"]),
        ]
        for group in groups {
        for file in group.files {
            let url = TestPaths.testDataDir.appendingPathComponent(file)
            guard let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
            for line in text.split(separator: "\n") {
                guard let data = line.data(using: .utf8),
                      let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                      let q = obj["q"] as? String else { continue }
                let pounds = (obj["pounds"] as? [String] ?? []).map { $0.replacingOccurrences(of: ",", with: "") }
                let ans = FinanceRouter.answer(q, rows: group.rows, currency: "GBP", money: Self.gbp)
                guard let a = ans else { deferred += 1; continue }
                answered += 1
                // hard-gate only the reliably-checkable single-answer questions
                if isLLMTerritory(q) { llmTerritory += 1; continue }
                guard !isComparison(q), !isRowIndex(q), let expected = pounds.first else { continue }
                _ = expected
                let out = a.replacingOccurrences(of: ",", with: "")
                guard out.contains("£") else { continue }
                checkable += 1
                // A "No transactions ..." reply is a valid £0 answer (e.g. nothing over £100).
                if out.contains("No transactions") && pounds.contains("£0.00") { continue }
                var shares = pounds.contains { out.contains($0) }
                // Averages are derived means: an exact half-penny (e.g. £21.025)
                // rounds differently under banker's vs printf half-up rounding, so
                // allow the router's figure within 1p of the expected average.
                if !shares, q.lowercased().contains("average") || q.lowercased().contains("typical"),
                   let exp = Self.firstPence(expected) {
                    shares = Self.allPence(out).contains { abs($0 - exp) <= 1 }
                }
                if !shares {
                    wrong.append("WRONG | \(q) | expected one of \(pounds) | got: \(out.replacingOccurrences(of: "\n", with: " / "))")
                }
            }
        }
        }
        print("=== BULK 46000 (set1..set6): answered \(answered), deferred-to-LLM \(deferred), llm-territory \(llmTerritory) | hard-checked \(checkable), wrong \(wrong.count) ===")
        for w in wrong.prefix(80) { print("FAIL| " + w) }
        XCTAssertTrue(wrong.isEmpty, "\(wrong.count) reliably-checkable router answers contradicted the verified figure")
    }
    // Focused loop target: the two bank CURRENT-ACCOUNT datasets (balance / income
    // / transfers / fees surface the Amex card sets never exercised). Fast to run.
    func testBankAccountsThroughRouter() throws {
        var answered = 0, deferred = 0, checkable = 0, llmTerritory = 0
        var wrong: [String] = []
        let groups: [(rows: [TxnRow], files: [String])] = [
            (Self.rowsBarclays, ["barclays_qa.jsonl"]),
            (Self.rowsMonzo,    ["monzo_qa.jsonl"]),
        ]
        for group in groups {
        for file in group.files {
            let url = TestPaths.testDataDir.appendingPathComponent(file)
            guard let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
            for line in text.split(separator: "\n") {
                guard let data = line.data(using: .utf8),
                      let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                      let q = obj["q"] as? String else { continue }
                let pounds = (obj["pounds"] as? [String] ?? []).map { $0.replacingOccurrences(of: ",", with: "") }
                guard let a = FinanceRouter.answer(q, rows: group.rows, currency: "GBP", money: Self.gbp) else { deferred += 1; continue }
                answered += 1
                if isLLMTerritory(q) { llmTerritory += 1; continue }
                guard !isComparison(q), !isRowIndex(q), let expected = pounds.first else { continue }
                _ = expected
                let out = a.replacingOccurrences(of: ",", with: "")
                guard out.contains("£") else { continue }
                checkable += 1
                if out.contains("No transactions") && pounds.contains("£0.00") { continue }
                var shares = pounds.contains { out.contains($0) }
                if !shares, q.lowercased().contains("average") || q.lowercased().contains("typical"),
                   let exp = Self.firstPence(expected) {
                    shares = Self.allPence(out).contains { abs($0 - exp) <= 1 }
                }
                if !shares {
                    wrong.append("WRONG | \(q) | expected one of \(pounds) | got: \(out.replacingOccurrences(of: "\n", with: " / "))")
                }
            }
        }
        }
        print("=== BANK (Barclays+Monzo): answered \(answered), deferred \(deferred), llm \(llmTerritory) | hard-checked \(checkable), wrong \(wrong.count) ===")
        for w in wrong.prefix(80) { print("FAIL| " + w) }
        XCTAssertTrue(wrong.isEmpty, "\(wrong.count) bank router answers contradicted the verified figure")
    }
